#include <atomic>
#include <iostream>
#include <thread>

std::atomic<int> sharedCounter(0);

void incrementCounter(int times) {
    for (int i = 0; i < times; ++i) {
        int expected = sharedCounter.load();
        while (!sharedCounter.compare_exchange_strong(expected, expected + 1)) {
            // Retry if another thread modified the value
        }
    }
}

int main() {
    std::thread t1(incrementCounter, 1000);
    std::thread t2(incrementCounter, 1000);
    t1.join();
    t2.join();
    std::cout << "Final counter: " << sharedCounter << std::endl;  // Should be 2000
    return 0;
}
